				Title: "Fuzzy find",
				Body:  "Press g to jump straight to a directory anywhere under the workspaces root, without drilling down level by level. Type at least 3 characters to search; move through the ranked results with ↑↓ and press Enter to land in that directory's parent listing with it selected, or Esc to cancel. The search covers directories only — not files — and does not descend into a git repository's own contents, mirroring how S, F and A discover nested repositories.",
			},
			{
				Title: "Git Status",
				Body:  "Directories that are git repositories display their branch name and status indicators: modified files, untracked files, unpushed commits, and unpulled commits. The unpulled count comes from the local remote-tracking ref, so it is only as fresh as the last fetch — press F to bring it up to date.",
			},
			{
				Title: "Sync",
				Body:  "Press F on a git repo to fetch its remote and fast-forward the current branch. On a non-git directory, F syncs every nested git repo. Sync never merges, rebases, stashes or pushes: a repository with uncommitted changes, with local commits the remote does not have, or on a detached HEAD is fetched and then left exactly as it was, and the footer says which one it was and why. The fetch happens either way, so a repository it declines still ends up showing how far behind it really is.",
func batchSyncCmd(repoPaths []string, spec syncSpec) tea.Cmd {
	sem := make(chan struct{}, max(spec.jobs, 1))
	cmds := make([]tea.Cmd, len(repoPaths))
	for i, path := range repoPaths {
		cmds[i] = syncOneRepoCmd(path, spec, sem)
	}
	return tea.Batch(cmds...)
}

// readGitStatus re-reads one repository's git metadata.
func readGitStatus(repoPath string) Entry {
	entry := Entry{Path: repoPath, IsDir: true}
	detectGitStatus(&entry)
	return entry
}

// loadScanCacheCmd loads the workspace scan cache from disk asynchronously
func loadScanCacheCmd() tea.Cmd {
	return func() tea.Msg {
		c, err := cache.NewWorkspaceScanCache(config.CurrentContextName())
		if err != nil {
			return ScanCacheLoadedMsg{Cache: nil}
		}
		return ScanCacheLoadedMsg{Cache: c.GetAll()}
	}
}
